/** Actual installed-owner slot matrix, material/reload retirement and section-boundary visibility. */
@EventBusSubscriber(modid="vandorlabs",value=Dist.CLIENT)
public final class ProgrammerRenderWorldChecks {
 private static int stage,phase,ticks,sent,draws,upperDraws,upperSkips,projected=-1;private static boolean enabled=true,captured,ending,sectionVisible,boundsVisible;private static String capture;
 private static NativeProgrammerBlockRenderer renderer,oldRenderer;private static Object casing,oldJournal;private static CompletableFuture<Void> reload;
 private static int[] pad,body;private static final JsonArray profiles=new JsonArray();private static final JsonObject metadata=new JsonObject();
 @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD,value=Dist.CLIENT)public static final class Binding{@SubscribeEvent public static void renderers(EntityRenderersEvent.RegisterRenderers event){if(ProgrammerRenderWorldFixture.enabled())event.registerBlockEntityRenderer(ProgrammerHostChecks.entityType(),context->new net.minecraft.client.renderer.blockentity.BlockEntityRenderer<NativeProgrammerEntity>(){private final NativeProgrammerBlockRenderer actual=new NativeProgrammerBlockRenderer(context);{renderer=actual;}public void render(NativeProgrammerEntity owner,float partial,PoseStack poses,net.minecraft.client.renderer.MultiBufferSource buffers,int light,int overlay){if(enabled){draws++;if(owner.getBlockPos().equals(ProgrammerRenderWorldFixture.UPPER))upperDraws++;actual.render(owner,partial,poses,buffers,light,overlay);}else if(owner.getBlockPos().equals(ProgrammerRenderWorldFixture.UPPER))upperSkips++;}public AABB getRenderBoundingBox(NativeProgrammerEntity owner){return actual.getRenderBoundingBox(owner);}public boolean shouldRenderOffScreen(NativeProgrammerEntity owner){return actual.shouldRenderOffScreen(owner);}public int getViewDistance(){return actual.getViewDistance();}});}}
 private static void need(boolean ok,String why){if(!ok)throw new AssertionError("Programmer placed-render stage="+stage+" phase="+phase+": "+why);}
 private static void ack(){PacketDistributor.sendToServer(new ProgrammerRenderWorldFixture.Ack(stage));stage++;phase=0;sent=ticks;projected=-1;}
 private static void shot(String name){capture=name;captured=false;sent=ticks;}
 private static NativeProgrammerEntity at(Minecraft mc,net.minecraft.core.BlockPos pos){return mc.level.getBlockEntity(pos) instanceof NativeProgrammerEntity owner?owner:null;}
 @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception{if(!ProgrammerRenderWorldFixture.enabled())return;var mc=Minecraft.getInstance();if(ending){if(mc.level==null&&mc.getOverlay()==null){ProgrammerMaterialGenerationProbe.unloaded(renderer);mc.options.hideGui=false;System.out.println("[vandorlabs][programmer-render-world] client PASS isolated24docks/4facings/bothkinds/allslots/material-only/reload/upper-only/disabled/unload");mc.stop();}return;}if(mc.player==null||mc.level==null||mc.gameMode==null)return;ticks++;need(ticks<10000,"timeout mode="+mc.gameMode.getPlayerMode()+" pos="+mc.player.position()+" held="+mc.player.getMainHandItem());if(ticks%200==0)System.out.println("[vandorlabs][programmer-render-world] waiting stage="+stage+" phase="+phase+" draws="+draws+" upper="+upperDraws);var low=mc.level.getBlockState(ProgrammerRenderWorldFixture.ACK);var high=mc.level.getBlockState(ProgrammerRenderWorldFixture.HIGH);if(!low.is(Blocks.NOTE_BLOCK)||!high.is(Blocks.NOTE_BLOCK)||low.getValue(NoteBlock.NOTE)+25*high.getValue(NoteBlock.NOTE)!=stage){need(ticks<sent+400,"server acknowledgement timeout");return;}if(stage==ProgrammerRenderWorldFixture.FINAL){metadata.add("profiles",profiles);java.nio.file.Files.writeString(mc.gameDirectory.toPath().resolve("programmer-world-projections.json"),new Gson().toJson(metadata));mc.level.disconnect();mc.disconnect();ending=true;return;}
  mc.options.hideGui=true;mc.options.bobView().set(false);mc.options.cloudStatus().set(CloudStatus.OFF);mc.options.fovEffectScale().set(0D);mc.options.fov().set(stage>=50?30:70);var expected=ProgrammerRenderWorldFixture.eye(stage);if(mc.getOverlay()!=null||mc.screen!=null||mc.gameMode.getPlayerMode()!=GameType.CREATIVE||!mc.player.getAbilities().flying||mc.player.getInventory().selected!=0||!mc.player.getMainHandItem().isEmpty()||mc.player.getEyePosition().distanceToSqr(expected)>.001)return;var owner=at(mc,stage>=49?ProgrammerRenderWorldFixture.UPPER:ProgrammerRenderWorldFixture.ROOT);if(owner==null||owner.visual().inert())return;
  if(stage<48){if(owner.getBlockState().getValue(NativeProgrammerBlock.FACING)!=ProgrammerRenderWorldFixture.face(stage))return;for(int slot=0;slot<3;slot++){int kind=stage%2==1&&slot==ProgrammerRenderWorldFixture.slot(stage)?ProgrammerRenderWorldFixture.chip(stage)?2:1:0;if(owner.visual().slots().get(slot).kind()!=kind||kind>0&&owner.visual().slots().get(slot).company()!=slot+1)return;}if(phase==0){if(ticks<sent+20)return;draws=0;shot(String.format(java.util.Locale.ROOT,"programmer-dock-%02d-%s.png",stage/2,stage%2==0?"empty":"occupied"));phase=1;}else if(captured){need(draws>0&&pad!=null&&body!=null,"actual draw and projected authored pad");if(stage%2==1){var row=new JsonObject();row.addProperty("profile",stage/2);row.addProperty("facing",ProgrammerRenderWorldFixture.face(stage).name());row.addProperty("slot",ProgrammerRenderWorldFixture.slot(stage));row.addProperty("chip",ProgrammerRenderWorldFixture.chip(stage));row.add("pad",new Gson().toJsonTree(pad));row.add("body",new Gson().toJsonTree(body));profiles.add(row);}ack();}return;}
  if(stage==48){if(owner.journalView()==null)return;switch(phase){case 0->{if(ticks<sent+20)return;shot("programmer-journal-before.png");phase=1;}case 1->{if(!captured)return;metadata.add("journalBody",new Gson().toJsonTree(body));ProgrammerMaterialGenerationProbe.start(renderer);phase=2;sent=ticks;}case 2->{if(ticks<sent+8)return;ProgrammerMaterialGenerationProbe.changed();shot("programmer-journal-material.png");phase=3;}case 3->{if(!captured)return;ProgrammerMaterialGenerationProbe.restore();phase=4;sent=ticks;}case 4->{if(ticks<sent+8)return;ProgrammerMaterialGenerationProbe.restored();casing=NativeProgrammerResources.currentBake();oldRenderer=renderer;oldJournal=ProgrammerMaterialGenerationProbe.current(renderer);reload=mc.reloadResourcePacks();phase=5;sent=ticks;}case 5->{if(!reload.isDone()||mc.getOverlay()!=null||ticks<sent+100)return;reload.join();need(casing!=NativeProgrammerResources.currentBake(),"actual new atlas generation");ProgrammerMaterialGenerationProbe.retired(oldJournal);need(renderer!=oldRenderer,"actual dispatcher renderer reload");shot("programmer-journal-reloaded.png");phase=6;}case 6->{if(captured)ack();}}return;}
  if(stage==49){if(owner.journalView()!=null&&ticks>sent+20)ack();return;}
  if(stage==50){if(phase==0){if(ticks<sent+20)return;upperDraws=0;shot("programmer-upper-only-positive.png");phase=1;}else if(captured){need(upperDraws>0&&!sectionVisible&&boundsVisible,"actual upper-only dispatch with owner section outside frustum");var proof=new JsonObject();proof.addProperty("originSectionVisible",sectionVisible);proof.addProperty("ownerBoundsVisible",boundsVisible);proof.addProperty("draws",upperDraws);metadata.add("upperOnly",proof);ack();}return;}
  if(stage==51){if(phase==0){enabled=false;upperSkips=0;shot("programmer-upper-only-disabled.png");phase=1;}else if(captured){need(upperSkips>0,"upper negative actually dispatched and suppressed");enabled=true;ack();}}
 }
 private static int[] project(RenderLevelStageEvent event,Direction face,double minX,double minY,double minZ,double maxX,double maxY,double maxZ){var mc=Minecraft.getInstance();var layout=NativeProgrammerLayout.of(face);var a=layout.transform();var camera=event.getCamera().getPosition();double left=Double.POSITIVE_INFINITY,top=left,right=-left,bottom=-left;for(int corner=0;corner<8;corner++){double x=(corner&1)==0?minX:maxX,y=(corner&2)==0?minY:maxY,z=(corner&4)==0?minZ:maxZ;var point=new Vector4f((float)(ProgrammerRenderWorldFixture.ROOT.getX()+layout.originX()+a.x(x,z)-camera.x),(float)(96+y-camera.y),(float)(ProgrammerRenderWorldFixture.ROOT.getZ()+layout.originZ()+a.z(x,z)-camera.z),1).mul(event.getModelViewMatrix()).mul(event.getProjectionMatrix());need(point.w>0,"projected authored point in front of camera");double px=(point.x/point.w*.5+.5)*mc.getWindow().getWidth(),py=(.5-point.y/point.w*.5)*mc.getWindow().getHeight();left=Math.min(left,px);right=Math.max(right,px);top=Math.min(top,py);bottom=Math.max(bottom,py);}return new int[]{(int)Math.floor(left)-5,(int)Math.floor(top)-5,(int)Math.ceil(right)+6,(int)Math.ceil(bottom)+6};}
 @SubscribeEvent public static void world(RenderLevelStageEvent event){if(!ProgrammerRenderWorldFixture.enabled()||event.getStage()!=RenderLevelStageEvent.Stage.AFTER_BLOCK_ENTITIES||Minecraft.getInstance().level==null)return;if(stage<=48&&projected!=stage&&capture!=null){Direction face=ProgrammerRenderWorldFixture.face(stage);body=project(event,face,0,0,0,2,2,1);int slot=ProgrammerRenderWorldFixture.slot(stage);pad=project(event,face,(slot==0?9:slot==1?25:1)/16D,16.02/16, (slot==0?8:1)/16D,(slot==0?23:slot==1?31:7)/16D,16.85/16,14D/16);projected=stage;}if(stage==50){sectionVisible=event.getFrustum().isVisible(new AABB(0,96,-16,16,112,0));var owner=at(Minecraft.getInstance(),ProgrammerRenderWorldFixture.UPPER);if(owner!=null)boundsVisible=event.getFrustum().isVisible(renderer.getRenderBoundingBox(owner));}}
 @SubscribeEvent public static void frame(RenderFrameEvent.Post event){if(!ProgrammerRenderWorldFixture.enabled()||capture==null||ticks<sent+12)return;String name=capture;capture=null;var mc=Minecraft.getInstance();Screenshot.grab(mc.gameDirectory,name,mc.getMainRenderTarget(),ignored->captured=true);}
}
